mapper.select:


SELECT COUNT(1)
FROM pcd_directory_closure_table
WHERE ancestor_id = #{ancestorId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
AND descendant_id = #{descendantId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
AND ((#{currentSpaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler} is null and user_id=#{userId,typeHandler=org.project.util.UUIDBinaryTypeHandler})
  OR closure_space_id=#{currentSpaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  OR (#{personalSpace}=true and closure_space_id is null
      AND user_id=#{userId,typeHandler=org.project.util.UUIDBinaryTypeHandler}))

SELECT c.descendant_id AS descendantId, c.ancestor_id AS ancestorId, n.node_name AS nodeName, c.depth AS depth FROM pcd_directory_closure_table c INNER JOIN pcd_directory_tree_table n ON c.ancestor_id = n.node_id WHERE c.descendant_id IN
#{id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
AND c.ancestor_id != #{rootNodeId,typeHandler=org.project.util.UUIDBinaryTypeHandler} AND ((#{currentSpaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler} is null and c.user_id=#{userId,typeHandler=org.project.util.UUIDBinaryTypeHandler}) OR c.closure_space_id=#{currentSpaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler} OR (#{personalSpace}=true and c.closure_space_id is null AND c.user_id=#{userId,typeHandler=org.project.util.UUIDBinaryTypeHandler})) ORDER BY c.descendant_id, c.depth DESC
